(* [comment removed for export] *)
Lemma stk_cell fxi Ri Mi mdi LKi Awi cri si smi eni ki ei Y q n :
  amid fxi Ri Mi mdi LKi Awi cri si smi eni ki ei Y -> sp - 160 <= q -> q + n <= sp - 104 -> 0 < n ->
  PMSPA.accA Mi q n /\ byte_at Mi (HeapIfaceA.S q) 0 /\ PMSAX.arg_ok ar FF' (sp - 160) (op + 360) q n
  /\ (forall v, L5.u32_at RSEGS (mrestrict (ahid Awi mdi) Mi) q v -> n = 4 -> L5.u32_at RSEGS Mi q v)
