(* [comment removed for export] *)
Lemma call_pushq (pc : Z) Q A0 cells (SPEC : PMBPQ.pushq_spec_at RSEGS AD L ar HI pc Q A0 cells) (t : UbjRef.pstate) (ra : Z)
      fxi Ri Mi mdi LKi Awi cri si smi eni ki ei Y :
  amid fxi Ri Mi mdi LKi Awi cri si smi eni ki ei Y ->
  getr Ri (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr Ri (reg 10) = Z_to_bv 64 (op + 360) ->
  cells FF' (sp - 160) (op + 360) Mi Ri (PEC.ps_conv t) ->
  Q (PM.p_b si) (PM.p_k si) (PM.p_stk si) (PM.vec_own (PM.p_b si) (PM.p_k si)) ->
  PM.pstate_ok (PEC.ps_conv t) -> ~ PM.mode_bottom (PM.ps_mode (PEC.ps_conv t)) ->
  Z.of_nat (length (PM.p_stk si)) <= PM.MAX_DEPTH ->
  (forall (fx' : FPState) R' M' md' LK' Aw' b' k' cr', regs_preserved Ri R' ->
      amid fx' R' M' md' LK' Aw' cr' (PMBBK.push_st si b' k' (PEC.ps_conv t)) smi eni ki ei (w_stk (t :: s_stk Y) Y) ->
      PMSAX.push_out L false (PM.p_b si) (PM.p_k si) (PM.p_stk si) (PM.vec_own (PM.p_b si) (PM.p_k si)) b' k' cri cr' ->
      A0 R' b' (PM.p_stk si ++ [PEC.ps_conv t]) ->
      (forall a, sp - 160 <= a < sp -> M' (Z_to_bv 64 a) = Mi (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (PMSPA.cfg (fx:=fx') RSEGS R' ra M' md') K) ->
  srealizes RSEGS SCFG (PMSPA.cfg (fx:=fxi) RSEGS Ri pc Mi mdi) K.
Proof.
