Lemma vec_hdr fxi Ri Mi mdi LKi Awi cri si smi eni ki ei Y :
  amid fxi Ri Mi mdi LKi Awi cri si smi eni ki ei Y ->
  let MVi := mrestrict (ahid Awi mdi) Mi in
  L5.u64_at RSEGS MVi (op + 368) (PM.p_b si + 32 * Z.of_nat (length (PM.p_stk si)))
  /\ L5.u64_at RSEGS MVi (op + 376) (PM.p_b si + 32 * 2 ^ PM.p_k si)
  /\ L5.defined MVi (op + 368) 8
  /\ 4096 <= PM.p_b si /\ PM.p_b si + 32 * 2 ^ PM.p_k si <= 2 ^ 47 /\ PM.p_b si mod 16 = 0
