  L5SAR.ek L ar (PEC.owned s en k ++ LBX) FF sp 26624 [] M1 M2 -> L5SAR.dk L ar (PEC.owned s en k ++ LBX) FF sp 26624 M1 M2 ->
  (forall a, sp - 160 <= a < sp -> M2 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
